import"./chunk-VC46IEJQ.js";var t=([a,s])=>({en:a,zh:s}),e=(a,s,o,r,i,h,l,d,n)=>({name:t(a),desc:t(s),tour:t(o),...n?{spoiler:t(n)}:{},source:{confidence:r,refs:i,book:t(h),unknown:t(l),interpretation:t(d)}}),w={id:"oldtown",intro:{en:"Oldtown, the oldest city in Westeros, stands where the Honeywine flows into the Whispering Sound. The Hightower and its beacon rise over the harbour; along the river lie the Citadel of the maesters and the Starry Sept.",zh:"\u65E7\u9547\u662F\u7EF4\u65AF\u7279\u6D1B\u6700\u53E4\u8001\u7684\u57CE\u5E02\uFF0C\u5750\u843D\u5728\u871C\u9152\u6CB3\u6CE8\u5165\u4F4E\u8BED\u6E7E\u4E4B\u5904\u3002\u53C2\u5929\u5854\u4E0E\u5854\u9876\u70FD\u706B\u9AD8\u8038\u4E8E\u6E2F\u53E3\u4E4B\u4E0A\uFF1B\u6CBF\u6CB3\u800C\u4E0A\uFF0C\u4FBF\u662F\u5B66\u58EB\u7684\u5B66\u57CE\u4E0E\u661F\u8FB0\u5723\u5802\u3002"},notes:{en:"From the novels (mainly A Feast for Crows) and the companion book: the Hightower and its beacon on Battle Isle, the Citadel on both banks of the Honeywine with its ravenry, the Quill and Tankard on a river island, the Starry Sept, a busy harbour and the walls. Invented: all plans, proportions, building shapes, street layout, colours and the tower's number of tiers.",zh:"\u5C0F\u8BF4\uFF08\u4E3B\u8981\u662F\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\uFF09\u4E0E\u8BBE\u5B9A\u96C6\u786E\u7ACB\uFF1A\u6218\u6597\u5C9B\u4E0A\u7684\u53C2\u5929\u5854\u53CA\u5854\u9876\u70FD\u706B\uFF0C\u6A2A\u8DE8\u871C\u9152\u6CB3\u4E24\u5CB8\u7684\u5B66\u57CE\u53CA\u5176\u9E26\u5DE2\uFF0C\u6CB3\u4E2D\u5C0F\u5C9B\u4E0A\u7684\u201C\u7FBD\u6BDB\u7B14\u4E0E\u9152\u676F\u201D\uFF0C\u661F\u8FB0\u5723\u5802\uFF0C\u7E41\u5FD9\u7684\u6E2F\u53E3\u4E0E\u57CE\u5899\u3002\u81EA\u884C\u8BBE\u8BA1\uFF1A\u5168\u90E8\u5E73\u9762\u3001\u6BD4\u4F8B\u3001\u5EFA\u7B51\u9020\u578B\u3001\u8857\u9053\u5E03\u5C40\u3001\u8272\u5F69\u53CA\u53C2\u5929\u5854\u7684\u5C42\u6570\u3002"},tour:["harbor","hightower","beacon","battle-isle","honeywine","starry-sept","citadel","citadel-bridges","ravenry","citadel-library","quill-and-tankard","streets-and-markets","old-walls"],sources:[{ref:"affc",checked:"memory",note:{en:"The prologue (a novice at the Citadel and the Quill and Tankard) and Samwell's arrival by sea in the last chapters. Recalled, not re-read.",zh:"\u5E8F\u7AE0\uFF08\u5B66\u57CE\u7684\u4E00\u540D\u5B66\u5F92\u4E0E\u201C\u7FBD\u6BDB\u7B14\u4E0E\u9152\u676F\u201D\u9152\u9986\uFF09\u4EE5\u53CA\u5C71\u59C6\u5728\u672B\u51E0\u7AE0\u4E58\u8239\u62B5\u8FBE\u65E7\u9547\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"House Hightower's history, the Hightower's ancient base and the Starry Sept as the old seat of the High Septons, confirmed by search summaries of wiki pages, not the book.",zh:"\u6D77\u5854\u5C14\u5BB6\u65CF\u7684\u5386\u53F2\u3001\u53C2\u5929\u5854\u53E4\u8001\u7684\u5854\u57FA\uFF0C\u4EE5\u53CA\u661F\u8FB0\u5723\u5802\u66FE\u4E3A\u5386\u4EE3\u5927\u4E3B\u6559\u9A7B\u5730\uFF0C\u5747\u7531\u7EF4\u57FA\u9875\u9762\u7684\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF0C\u672A\u67E5\u539F\u4E66\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"The Honeywine opening into the Whispering Sound, bridges at the Citadel and shrine gardens: search summaries only; pages not fetched.",zh:"\u871C\u9152\u6CB3\u6CE8\u5165\u4F4E\u8BED\u6E7E\u3001\u5B66\u57CE\u7684\u6865\u6881\u4E0E\u795E\u9F9B\u82B1\u56ED\uFF1A\u4EC5\u89C1\u641C\u7D22\u6458\u8981\uFF0C\u9875\u9762\u672A\u6293\u53D6\u3002"}}],landmarks:{hightower:e(["The Hightower","\u53C2\u5929\u5854"],["The tallest tower in Westeros, rising in pale tiers from Battle Isle above the harbour; seat of House Hightower.","\u7EF4\u65AF\u7279\u6D1B\u6700\u9AD8\u7684\u5854\uFF0C\u6D45\u8272\u5854\u8EAB\u5C42\u5C42\u6536\u5206\uFF0C\u81EA\u6218\u6597\u5C9B\u62D4\u5730\u800C\u8D77\uFF0C\u4FEF\u77B0\u6E2F\u53E3\uFF0C\u662F\u6D77\u5854\u5C14\u5BB6\u65CF\u7684\u5C45\u57CE\u3002"],["Said to be taller than the Wall, it is the first thing every ship sees.","\u636E\u8BF4\u5B83\u6BD4\u957F\u57CE\u8FD8\u9AD8\uFF0C\u6BCF\u8258\u6765\u8239\u6700\u5148\u671B\u89C1\u7684\u5C31\u662F\u5B83\u3002"],"high",["affc","twoiaf"],["A colossal tower with a beacon on Battle Isle, held by House Hightower; the companion book calls it the tallest structure in Westeros and says its oldest base is a mysterious black-stone fortress.","\u6218\u6597\u5C9B\u4E0A\u7684\u5DE8\u5854\uFF0C\u9876\u6709\u70FD\u706B\uFF0C\u7531\u6D77\u5854\u5C14\u5BB6\u65CF\u636E\u5B88\uFF1B\u8BBE\u5B9A\u96C6\u79F0\u5B83\u662F\u7EF4\u65AF\u7279\u6D1B\u6700\u9AD8\u7684\u5EFA\u7B51\uFF0C\u6700\u53E4\u8001\u7684\u5854\u57FA\u662F\u4E00\u5EA7\u6765\u5386\u6210\u8C1C\u7684\u9ED1\u77F3\u5821\u5792\u3002"],["Its exact height, number of tiers and interior.","\u786E\u5207\u9AD8\u5EA6\u3001\u5C42\u6570\u4E0E\u5185\u90E8\u5E03\u5C40\u3002"],["Six round tiers of pale stone, each narrower than the last. Height is scaled down (fan estimates run to some 800 ft).","\u516D\u5C42\u6D45\u8272\u77F3\u5854\uFF0C\u9010\u5C42\u6536\u7A84\u3002\u9AD8\u5EA6\u5DF2\u6309\u6BD4\u4F8B\u7F29\u5C0F\uFF08\u7231\u597D\u8005\u4F30\u7B97\u7EA6\u516B\u767E\u5C3A\uFF09\u3002"],["Lord Leyton Hightower is said to have shut himself away at the top with his daughter, poring over old books.","\u636E\u8BF4\u96F7\u987F\xB7\u6D77\u5854\u5C14\u5927\u4EBA\u4E0E\u5973\u513F\u95ED\u5C45\u5854\u9876\uFF0C\u57CB\u9996\u53E4\u7C4D\u3002"]),beacon:e(["The Beacon","\u5854\u9876\u70FD\u706B"],["A great fire burning at the very top, guiding ships and visible far out to sea.","\u5854\u9876\u957F\u71C3\u7684\u5DE8\u706B\uFF0C\u4E3A\u8239\u53EA\u5F15\u822A\uFF0C\u8FDC\u5728\u6D77\u4E0A\u4EA6\u53EF\u671B\u89C1\u3002"],["The beacon on the crown guides ships in by night.","\u5854\u9876\u7684\u70FD\u706B\u5728\u591C\u91CC\u4E3A\u6765\u8239\u5F15\u8DEF\u3002"],"high",["affc","twoiaf"],["A beacon fire burns atop the Hightower, serving as a lighthouse for the port.","\u53C2\u5929\u5854\u9876\u71C3\u7740\u70FD\u706B\uFF0C\u5145\u5F53\u6E2F\u53E3\u7684\u706F\u5854\u3002"],["How it is fuelled and tended, and what the lantern looks like.","\u71C3\u6599\u4E0E\u770B\u62A4\u65B9\u5F0F\uFF0C\u4EE5\u53CA\u706F\u5BA4\u6837\u8C8C\u3002"],["An open brazier under columns and a copper cap; the flame flickers and lights the tower at night.","\u7ACB\u67F1\u4E0E\u94DC\u76D6\u4E0B\u7684\u655E\u53E3\u706B\u76C6\uFF1B\u706B\u7130\u95EA\u52A8\uFF0C\u591C\u95F4\u7167\u4EAE\u5854\u8EAB\u3002"]),"battle-isle":e(["Battle Isle","\u6218\u6597\u5C9B"],["The island at the mouth of the Honeywine on which the Hightower stands.","\u871C\u9152\u6CB3\u53E3\u7684\u5C9B\u5C7F\uFF0C\u53C2\u5929\u5854\u77D7\u7ACB\u5176\u4E0A\u3002"],["The Hightower stands on its own walled island at the harbour mouth.","\u53C2\u5929\u5854\u72EC\u5360\u6E2F\u53E3\u5165\u53E3\u5904\u4E00\u5EA7\u6709\u57CE\u5899\u73AF\u7ED5\u7684\u5C0F\u5C9B\u3002"],"high",["affc","twoiaf"],["Battle Isle, where the Honeywine meets the Whispering Sound, carries the Hightower.","\u6218\u6597\u5C9B\u4F4D\u4E8E\u871C\u9152\u6CB3\u6CE8\u5165\u4F4E\u8BED\u6E7E\u4E4B\u5904\uFF0C\u5C9B\u4E0A\u7ACB\u7740\u53C2\u5929\u5854\u3002"],["How the island is reached and what else stands on it.","\u767B\u5C9B\u65B9\u5F0F\uFF0C\u4EE5\u53CA\u5C9B\u4E0A\u7684\u5176\u4ED6\u5EFA\u7B51\u3002"],["A round curtain wall with towers, a hall and stables stand for the isle's works.","\u4EE5\u5E26\u5854\u697C\u7684\u73AF\u5F62\u56F4\u5899\u3001\u5927\u5385\u4E0E\u9A6C\u53A9\u4EE3\u8868\u5C9B\u4E0A\u8BBE\u65BD\u3002"]),harbor:e(["The Harbour","\u6E2F\u53E3"],["One of the great harbours of the realm: quays, piers, warehouses and cranes on the Whispering Sound.","\u738B\u56FD\u7684\u5927\u6E2F\u4E4B\u4E00\uFF1A\u4F4E\u8BED\u6E7E\u7554\u7801\u5934\u3001\u6808\u6865\u3001\u8D27\u6808\u4E0E\u540A\u673A\u6797\u7ACB\u3002"],["Ships from across the Narrow Sea and the Summer Isles put in here.","\u6765\u81EA\u72ED\u6D77\u5BF9\u5CB8\u4E0E\u76DB\u590F\u7FA4\u5C9B\u7684\u8239\u53EA\u5728\u6B64\u9760\u5CB8\u3002"],"high",["affc","twoiaf"],["Oldtown is a major port and one of the largest cities in Westeros; Samwell arrives by sea.","\u65E7\u9547\u662F\u91CD\u8981\u6E2F\u53E3\uFF0C\u4E5F\u662F\u7EF4\u65AF\u7279\u6D1B\u6700\u5927\u7684\u57CE\u5E02\u4E4B\u4E00\uFF1B\u5C71\u59C6\u4ECE\u6D77\u8DEF\u62B5\u8FBE\u3002"],["Number of docks, quay layout and fleet size.","\u7801\u5934\u6570\u91CF\u3001\u5E03\u5C40\u4E0E\u8239\u961F\u89C4\u6A21\u3002"],["Straight quays with nine piers, warehouses and ships, arranged for decoration.","\u7B14\u76F4\u7684\u7801\u5934\u3001\u4E5D\u5EA7\u6808\u6865\u3001\u8D27\u6808\u4E0E\u8239\u53EA\uFF0C\u5747\u4E3A\u88C5\u9970\u6027\u5B89\u6392\u3002"]),"old-walls":e(["City Walls","\u57CE\u5899"],["Old stone walls and towers ring the landward side, with gates onto the roads.","\u53E4\u8001\u7684\u77F3\u5899\u4E0E\u5854\u697C\u73AF\u7ED5\u9646\u4FA7\uFF0C\u57CE\u95E8\u901A\u5F80\u5404\u6761\u5927\u9053\u3002"],["The walls open only where the river and the roads pass through.","\u57CE\u5899\u53EA\u5728\u6CB3\u6D41\u4E0E\u5927\u9053\u7A7F\u8FC7\u5904\u5F00\u53E3\u3002"],"medium",["twoiaf"],["Oldtown is a walled city.","\u65E7\u9547\u6709\u57CE\u5899\u3002"],["Wall height, gate names and the true circuit.","\u57CE\u5899\u9AD8\u5EA6\u3001\u57CE\u95E8\u540D\u79F0\u4E0E\u771F\u5B9E\u8D70\u5411\u3002"],["An oval circuit with a water gap for the Honeywine and three gatehouses; all invented.","\u692D\u5706\u5F62\u57CE\u57A3\uFF0C\u4E3A\u871C\u9152\u6CB3\u7559\u51FA\u6C34\u53E3\uFF0C\u8BBE\u4E09\u5EA7\u57CE\u95E8\u697C\uFF1B\u5747\u4E3A\u865A\u6784\u3002"]),"streets-and-markets":e(["Streets and Markets","\u8857\u5DF7\u4E0E\u96C6\u5E02"],["Winding cobbled streets of whitewashed houses with terracotta roofs, stalls and crowds.","\u873F\u8712\u7684\u5375\u77F3\u8857\u5DF7\uFF0C\u767D\u5899\u8D64\u74E6\uFF0C\u644A\u6863\u6797\u7ACB\uFF0C\u4EBA\u58F0\u9F0E\u6CB8\u3002"],["A warm, crowded southern city of cobbles, plaster and tile.","\u6E29\u6696\u62E5\u6324\u7684\u5357\u65B9\u57CE\u5E02\uFF1A\u5375\u77F3\u8DEF\u3001\u7070\u6CE5\u5899\u4E0E\u9676\u74E6\u9876\u3002"],"low",["affc"],["Oldtown is a crowded old city with cobbled streets and wynds.","\u65E7\u9547\u662F\u5EA7\u62E5\u6324\u7684\u8001\u57CE\uFF0C\u5375\u77F3\u8857\u9053\u4E0E\u7A84\u5DF7\u7EB5\u6A2A\u3002"],["The street plan and district names.","\u8857\u533A\u5E03\u5C40\u4E0E\u533A\u540D\u3002"],["Six main streets and scattered houses stand for the whole; colours chosen for a southern feel.","\u4EE5\u516D\u6761\u4E3B\u8857\u4E0E\u96F6\u6563\u623F\u5C4B\u4EE3\u8868\u5168\u57CE\uFF1B\u8272\u5F69\u53D6\u5357\u65B9\u98CE\u5473\u3002"]),honeywine:e(["The Honeywine","\u871C\u9152\u6CB3"],["The river that runs through the city and widens into the Whispering Sound past the Hightower.","\u7A7F\u57CE\u800C\u8FC7\u7684\u6CB3\u6D41\uFF0C\u6D41\u7ECF\u53C2\u5929\u5854\u540E\u6C47\u5165\u5BBD\u9614\u7684\u4F4E\u8BED\u6E7E\u3002"],["Along its banks stand the Citadel and the Starry Sept; downstream lies the sea.","\u5B66\u57CE\u4E0E\u661F\u8FB0\u5723\u5802\u5206\u5217\u4E24\u5CB8\uFF0C\u987A\u6D41\u800C\u4E0B\u4FBF\u662F\u5927\u6D77\u3002"],"high",["affc","twoiaf"],["The Honeywine flows through Oldtown; the Citadel stands on both its banks and it meets the sea at Battle Isle.","\u871C\u9152\u6CB3\u6D41\u7ECF\u65E7\u9547\uFF0C\u5B66\u57CE\u6A2A\u8DE8\u5176\u4E24\u5CB8\uFF0C\u6CB3\u6C34\u5728\u6218\u6597\u5C9B\u5904\u5165\u6D77\u3002"],["Its width, bends and course through the city.","\u6CB3\u5BBD\u3001\u6CB3\u6E7E\u4E0E\u7A7F\u57CE\u8DEF\u7EBF\u3002"],["A broad meandering channel with small boats; the bends are artistic.","\u5BBD\u9614\u873F\u8712\u7684\u6CB3\u9053\uFF0C\u5C0F\u8239\u5F80\u6765\uFF1B\u6CB3\u6E7E\u4E3A\u827A\u672F\u5904\u7406\u3002"]),"starry-sept":e(["Starry Sept","\u661F\u8FB0\u5723\u5802"],["The ancient seat of the High Septons, a many-towered temple of dark stone.","\u5386\u4EE3\u5927\u4E3B\u6559\u7684\u53E4\u8001\u9A7B\u5730\uFF0C\u4E00\u5EA7\u6DF1\u8272\u77F3\u6599\u7684\u591A\u5854\u5723\u5802\u3002"],["For a thousand years the High Septons led the Faith from here.","\u5343\u767E\u5E74\u6765\uFF0C\u5386\u4EFB\u5927\u4E3B\u6559\u90FD\u5728\u6B64\u7EDF\u9886\u4E03\u795E\u4FE1\u4EF0\u3002"],"medium",["affc","twoiaf"],["The Starry Sept was the seat of the High Septon until the Great Sept of Baelor was built in King's Landing.","\u5728\u541B\u4E34\u7684\u8D1D\u52D2\u5927\u5723\u5802\u5EFA\u6210\u4E4B\u524D\uFF0C\u661F\u8FB0\u5723\u5802\u4E00\u76F4\u662F\u5927\u4E3B\u6559\u7684\u9A7B\u5730\u3002"],["Its colour, shape and number of towers.","\u989C\u8272\u3001\u9020\u578B\u4E0E\u5854\u697C\u6570\u91CF\u3002"],["Seven spired towers around a central spire echo the Seven; the dark stone follows wiki descriptions.","\u4E03\u5EA7\u5C16\u5854\u73AF\u7ED5\u4E2D\u592E\u5C16\u5854\uFF0C\u547C\u5E94\u4E03\u795E\uFF1B\u6DF1\u8272\u77F3\u6599\u4F9D\u636E\u7EF4\u57FA\u63CF\u8FF0\u3002"]),"quill-and-tankard":e(["Quill and Tankard","\u7FBD\u6BDB\u7B14\u4E0E\u9152\u676F"],["A tall, old timbered inn on an island in the Honeywine, favoured by novices and maesters.","\u871C\u9152\u6CB3\u4E2D\u5C0F\u5C9B\u4E0A\u4E00\u5EA7\u9AD8\u8038\u7684\u8001\u6728\u6784\u9152\u9986\uFF0C\u5B66\u5F92\u4E0E\u5B66\u58EB\u90FD\u7231\u5149\u987E\u3002"],["An old inn on a river island where Citadel novices come to drink.","\u6CB3\u5FC3\u5C0F\u5C9B\u4E0A\u7684\u8001\u9152\u9986\uFF0C\u5B66\u57CE\u7684\u5B66\u5F92\u5E38\u6765\u8FD9\u91CC\u559D\u9152\u3002"],"medium",["affc","awoiaf"],["The Quill and Tankard is an old inn on an island in the Honeywine, opening A Feast for Crows.","\u201C\u7FBD\u6BDB\u7B14\u4E0E\u9152\u676F\u201D\u662F\u871C\u9152\u6CB3\u4E2D\u5C0F\u5C9B\u4E0A\u7684\u4E00\u5BB6\u8001\u9152\u9986\uFF0C\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u5373\u7531\u6B64\u5F00\u7BC7\u3002"],["Its exact island and appearance.","\u6240\u5728\u5C0F\u5C9B\u7684\u786E\u5207\u4F4D\u7F6E\u4E0E\u5916\u89C2\u3002"],["A timber inn on a small island above the Citadel; the location is invented.","\u5B66\u57CE\u4E0A\u6E38\u5C0F\u5C9B\u4E0A\u7684\u6728\u6784\u9152\u9986\uFF1B\u4F4D\u7F6E\u4E3A\u865A\u6784\u3002"]),citadel:e(["The Citadel","\u5B66\u57CE"],["The maesters' seat of learning: towers, domes and halls on both banks of the Honeywine.","\u5B66\u58EB\u4EEC\u7684\u6C42\u5B66\u5723\u5730\uFF1A\u871C\u9152\u6CB3\u4E24\u5CB8\u5854\u697C\u3001\u7A79\u9876\u4E0E\u5385\u5802\u6797\u7ACB\u3002"],["Every maester in the realm forges his chain here, link by link.","\u738B\u56FD\u7684\u6BCF\u4E00\u4F4D\u5B66\u58EB\u90FD\u5728\u8FD9\u91CC\u4E00\u73AF\u4E00\u73AF\u5730\u953B\u6210\u81EA\u5DF1\u7684\u9888\u94FE\u3002"],"high",["affc","twoiaf"],["The Citadel spreads along both banks of the Honeywine; archmaesters teach and novices study for their chain links.","\u5B66\u57CE\u6CBF\u871C\u9152\u6CB3\u4E24\u5CB8\u94FA\u5F00\uFF1B\u535A\u5B66\u58EB\u5728\u6B64\u6388\u4E1A\uFF0C\u5B66\u5F92\u5728\u6B64\u7814\u4E60\u4EE5\u8D62\u5F97\u9888\u94FE\u7684\u94FE\u73AF\u3002"],["The number, form and layout of its buildings.","\u5EFA\u7B51\u7684\u6570\u91CF\u3001\u5F62\u5236\u4E0E\u5E03\u5C40\u3002"],["Pale towers with green copper domes, a tall central tower and several halls; the plan is invented.","\u6D45\u8272\u5854\u697C\u914D\u94DC\u7EFF\u7A79\u9876\uFF0C\u4E00\u5EA7\u4E2D\u592E\u9AD8\u5854\u4E0E\u6570\u5EA7\u5385\u5802\uFF1B\u5E03\u5C40\u4E3A\u865A\u6784\u3002"],["Samwell learns that some archmaesters may have worked against dragons and magic.","\u5C71\u59C6\u5F97\u77E5\uFF0C\u90E8\u5206\u535A\u5B66\u58EB\u6216\u8BB8\u4E00\u76F4\u5728\u6697\u4E2D\u4E0E\u5DE8\u9F99\u548C\u9B54\u6CD5\u4E3A\u654C\u3002"]),ravenry:e(["The Ravenry","\u9E26\u5DE2"],["A tower full of ravens that carry the realm's messages.","\u517B\u6EE1\u6E21\u9E26\u7684\u5854\u697C\uFF0C\u738B\u56FD\u7684\u4E66\u4FE1\u7531\u6B64\u98DE\u51FA\u3002"],["Black and white ravens circle the oldest part of the Citadel.","\u9ED1\u767D\u4E24\u8272\u7684\u6E21\u9E26\u5728\u5B66\u57CE\u6700\u53E4\u8001\u7684\u5EFA\u7B51\u4E0A\u7A7A\u76D8\u65CB\u3002"],"medium",["affc","awoiaf"],["The ravenry stands on the Isle of Ravens, the Citadel's oldest building, with a weirwood drawbridge; white ravens are kept as well as black.","\u9E26\u5DE2\u4F4D\u4E8E\u5B66\u57CE\u6700\u53E4\u8001\u7684\u5EFA\u7B51\u6E21\u9E26\u5C9B\u4E0A\uFF0C\u6709\u4E00\u5EA7\u9C7C\u6881\u6728\u540A\u6865\uFF1B\u9664\u9ED1\u9E26\u5916\u8FD8\u9972\u517B\u767D\u9E26\u3002"],["Tower height and its position relative to the other buildings.","\u5854\u9AD8\u53CA\u5176\u4E0E\u5176\u4ED6\u5EFA\u7B51\u7684\u76F8\u5BF9\u4F4D\u7F6E\u3002"],["A slim grey tower with an open crown, ravens circling; not shown on an island.","\u4E00\u5EA7\u7EC6\u9AD8\u7070\u5854\uFF0C\u5854\u51A0\u655E\u5F00\uFF0C\u7FA4\u9E26\u76D8\u65CB\uFF1B\u672A\u8868\u73B0\u4E3A\u5C9B\u5C7F\u3002"]),"citadel-library":e(["The Library","\u85CF\u4E66\u697C"],["The Citadel's great store of books and scrolls; a cutaway shows an imagined vaulted hall.","\u5B66\u57CE\u6D69\u5982\u70DF\u6D77\u7684\u4E66\u5377\u6536\u85CF\uFF1B\u53EF\u8FDB\u5165\u5256\u9762\u67E5\u770B\u60F3\u8C61\u4E2D\u7684\u62F1\u9876\u5927\u5385\u3002"],["Lamps, shelves and long tables: the memory of the realm.","\u706F\u706B\u3001\u4E66\u67B6\u4E0E\u957F\u684C\uFF1A\u738B\u56FD\u7684\u8BB0\u5FC6\u6240\u5728\u3002"],"low",["affc","twoiaf"],["The Citadel holds the realm's largest collection of books. Samwell does not work in its library in the novels; that is a TV-series scene.","\u5B66\u57CE\u62E5\u6709\u738B\u56FD\u6700\u591A\u7684\u85CF\u4E66\u3002\u5C0F\u8BF4\u4E2D\u5C71\u59C6\u5E76\u672A\u5728\u85CF\u4E66\u697C\u5DE5\u4F5C\uFF0C\u90A3\u662F\u7535\u89C6\u5267\u7684\u60C5\u8282\u3002"],["Size, layout and architecture.","\u89C4\u6A21\u3001\u5E03\u5C40\u4E0E\u5EFA\u7B51\u98CE\u683C\u3002"],["Cutaway: a two-level vaulted hall with galleries, tables and ladders, wholly interpretive.","\u5256\u9762\uFF1A\u53CC\u5C42\u62F1\u9876\u5927\u5385\uFF0C\u914D\u56DE\u5ECA\u3001\u957F\u684C\u4E0E\u68AF\u5B50\uFF0C\u7EAF\u5C5E\u60F3\u8C61\u3002"]),"citadel-bridges":e(["Bridges","\u5B66\u57CE\u6865\u6881"],["Arched stone bridges cross the Honeywine; houses and stalls crowd their spans.","\u77F3\u62F1\u6865\u6A2A\u8DE8\u871C\u9152\u6CB3\uFF0C\u6865\u9762\u4E0A\u6324\u6EE1\u623F\u5C4B\u4E0E\u644A\u6863\u3002"],["Shops and homes sit right on the bridges.","\u5546\u94FA\u4E0E\u4F4F\u5B85\u5C31\u5EFA\u5728\u6865\u4E0A\u3002"],"low",["affc","awoiaf"],["Bridges link the two banks of the Citadel; houses and stalls on them are mentioned only in search summaries.","\u6865\u6881\u8FDE\u63A5\u5B66\u57CE\u4E24\u5CB8\uFF1B\u6865\u4E0A\u6709\u623F\u5C4B\u4E0E\u644A\u6863\u4E00\u8BF4\u4EC5\u89C1\u4E8E\u641C\u7D22\u6458\u8981\u3002"],["How many bridges there are and their form.","\u6865\u7684\u6570\u91CF\u4E0E\u5F62\u5236\u3002"],["Three arched bridges, two with small houses on them.","\u4E09\u5EA7\u62F1\u6865\uFF0C\u5176\u4E2D\u4E24\u5EA7\u6865\u4E0A\u5EFA\u6709\u5C0F\u5C4B\u3002"]),"shrine-gardens":e(["Shrine Gardens","\u795E\u9F9B\u82B1\u56ED"],["Gardens across the river from the Sept, dotted with seven small shrines.","\u5723\u5802\u5BF9\u5CB8\u7684\u82B1\u56ED\uFF0C\u6563\u5E03\u7740\u4E03\u5EA7\u5C0F\u795E\u9F9B\u3002"],["Seven small shrines face the Starry Sept across the water.","\u4E03\u5EA7\u5C0F\u795E\u9F9B\u9694\u6C34\u9065\u5BF9\u661F\u8FB0\u5723\u5802\u3002"],"low",["awoiaf"],["Search summaries place shrine gardens across the Honeywine from the Sept; we could not trace them to the novels.","\u641C\u7D22\u6458\u8981\u79F0\u5723\u5802\u5BF9\u5CB8\u6709\u795E\u9F9B\u82B1\u56ED\uFF1B\u6211\u4EEC\u672A\u80FD\u5728\u5C0F\u8BF4\u4E2D\u627E\u5230\u51FA\u5904\u3002"],["Size, number and form of the shrines.","\u795E\u9F9B\u7684\u89C4\u6A21\u3001\u6570\u91CF\u4E0E\u5F62\u5236\u3002"],["A ring of seven tiny tiled shrines with cypresses.","\u4E00\u5708\u4E03\u5EA7\u74E6\u9876\u5C0F\u795E\u9F9B\uFF0C\u914D\u67CF\u6811\u3002"])}};export{w as default};
